"use strict";

const https = require("node:https");

function codeOf(error) {
  return String(error && (error.autojs6Code || error.code || error.name || ""));
}

exports.probe = function probe() {
  return new Promise((resolve) => {
    const req = https.request("https://example.invalid/tls-fail", { timeout: 1000 }, (res) => {
      res.resume();
      res.on("end", () => resolve("httpnpm.tls-failure=allowed"));
    });
    req.on("error", (error) => {
      resolve("httpnpm.tls-failure=" + codeOf(error) + "|" + String(error && error.message || ""));
    });
    req.end();
  });
};
